inline bool VerifyAttribute(::flatbuffers::Verifier &verifier, const void *obj, Attribute type) {
  switch (type) {
    case Attribute_NONE: {
      return true;
    }
    case Attribute_HardOp: {
      auto ptr = reinterpret_cast<const flatbuffer::HardOp *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_Cast: {
      auto ptr = reinterpret_cast<const flatbuffer::Cast *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_ImageMake: {
      auto ptr = reinterpret_cast<const flatbuffer::ImageMake *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_Detpost: {
      auto ptr = reinterpret_cast<const flatbuffer::Detpost *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_Input: {
      auto ptr = reinterpret_cast<const flatbuffer::Input *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_Output: {
      auto ptr = reinterpret_cast<const flatbuffer::Output *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_SwapOrder: {
      auto ptr = reinterpret_cast<const flatbuffer::SwapOrder *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_Resize: {
      auto ptr = reinterpret_cast<const flatbuffer::Resize *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_AlignAxis: {
      auto ptr = reinterpret_cast<const flatbuffer::AlignAxis *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_PruneAxis: {
      auto ptr = reinterpret_cast<const flatbuffer::PruneAxis *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_Reorg: {
      auto ptr = reinterpret_cast<const flatbuffer::Reorg *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_Add: {
      auto ptr = reinterpret_cast<const flatbuffer::Add *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_Multiply: {
      auto ptr = reinterpret_cast<const flatbuffer::Multiply *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_Yolo: {
      auto ptr = reinterpret_cast<const flatbuffer::Yolo *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_SegPost: {
      auto ptr = reinterpret_cast<const flatbuffer::SegPost *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Attribute_WarpAffine: {
      auto ptr = reinterpret_cast<const flatbuffer::WarpAffine *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyAttributeVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyAttribute(
        verifier,  values->Get(i), types->GetEnum<Attribute>(i))) {
      return false;
    }
  }
  return true;
}

